import datetime
import re

from ta_moler.events.unix_syslog.genericunix_syslog_lineevent import GenericUnixSyslogLineEvent


class CellStatusFromOnlineToOffline(GenericUnixSyslogLineEvent):
    """CellStatusFromOnlineToOffline event class."""

    def __init__(self, connection, till_occurs_times=-1, cell_id=None, runner=None):
        """
        Event for 'Wait for cell status to change from Online to Offline'.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param cell_id: id of cell to wait for status change,
                        if cell_id = None, any cell will trigger this event
        :param runner: Runner to run event
        """
        if cell_id is None:
            detect_option = r"\d+"
        else:
            detect_option = cell_id

        # CELL_M-1 has been changed from Online to Offline
        self._re_detect_pattern = re.compile(f"(?P<CELL>CELL_M-{detect_option}) has been changed from Online to Offline")

        super(CellStatusFromOnlineToOffline, self).__init__(
            connection=connection, runner=runner, till_occurs_times=till_occurs_times, detect_patterns=[self._re_detect_pattern], match="any"
        )


